    // оснащения, но в ручном режиме это только предупреждения. Проверяем прежде всего
    // фактическую занятость кабинета на нужных неделях.
    const currentRoomFree = inst?.format === "remote" || !currentRoomId
      ? inst?.format === "remote"
      : roomAvailableIgnoringParticipantWarnings(inst, day, period, currentRoomId, weeklyPlanningMode ? scheduleWeek : 0).ok;
    const currentRoomOption = currentRoomId && currentRoomFree ? {
      roomId:currentRoomId, extraRoomId:current.extraRoomId || null, roomChanged:false,
      dedicatedOverride:!!(inst?.dedicatedRoomId && !roomIdsEquivalent(data.rooms,currentRoomId,inst.dedicatedRoomId)),
      manualKeepRoom:true
    } : null;
    const preferred = currentRoomOption || optionsResult.options.find((o) => roomIdsEquivalent(data.rooms, o.roomId, currentRoomId)) || optionsResult.options[0];
    // Окно смены кабинета показываем только когда фактически сохранить текущий
