      const roomName = byId(data.rooms, roomId)?.name || "выбранная аудитория";
      const ok = window.confirm(`⚠ Совместное занятие двух групп\n\n${teacherName} уже ведёт «${subjectName}» в это время в аудитории ${roomName}.\n\nВы собираетесь вручную добавить вторую группу к тому же преподавателю, предмету и аудитории. Автоматически система так пары не ставит.\n\nТочно поставить две группы вместе?`);
